"""E2e tests for category: proxy."""

import os

import pytest
from crawlberg import BrowserConfig, CrawlConfig, ProxyConfig, crawl, create_engine


@pytest.mark.asyncio
async def test_proxy_authenticated() -> None:
    """Proxy with username and password credentials authenticates successfully."""
    engine_config = CrawlConfig(
        browser=BrowserConfig(mode="never"),
        proxy=ProxyConfig(password="proxypass", url="http://127.0.0.1:8889", username="proxyuser"),
        respect_robots_txt=False,
    )
    engine = create_engine(engine_config)
    url = os.environ["MOCK_SERVER_URL"] + "/fixtures/proxy_authenticated"

    result = await crawl(engine, url)
    assert len(result.pages) == 0


